-- Building footprints for PAU from OpenStreetMap.
-- © OpenStreetMap contributors, Open Database License (ODbL).
-- Generated by tools/osm_to_campus.py. Safe to re-run: existing rows are updated by osm_id.
on conflict (osm_id) do update set
  name = coalesce(public.campus_buildings.name, excluded.name),
  category = excluded.category,
  levels = coalesce(public.campus_buildings.levels, excluded.levels),
  footprint = excluded.footprint,
  updated_at = now();

notify pgrst, 'reload schema';
